import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.Dkj3JE0_.js";const m=JSON.parse('{"title":"Bases de la grammaire japonaise","description":"","frontmatter":{"title":"Bases de la grammaire japonaise"},"headers":[],"relativePath":"fr/blogs/JLPT-N2/grammars.md","filePath":"fr/blogs/JLPT-N2/grammars.md"}'),r={name:"fr/blogs/JLPT-N2/grammars.md"};function o(i,e,l,u,d,p){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="bases-de-la-grammaire-japonaise" tabindex="-1">Bases de la grammaire japonaise <a class="header-anchor" href="#bases-de-la-grammaire-japonaise" aria-label="Permalink to &quot;Bases de la grammaire japonaise&quot;">​</a></h1><p>Ces constructions de base sont utiles à revoir avant d’aborder la grammaire N2. Dans les modèles ci-dessous, <strong>N</strong> désigne un nom et <strong>A/B</strong> les mots ou groupes de mots occupant les positions indiquées.</p><h2 id="a-は-b-です" tabindex="-1">A は B です <a class="header-anchor" href="#a-は-b-です" aria-label="Permalink to &quot;A は B です&quot;">​</a></h2><p><strong>Règle :</strong> は se prononce <em>wa</em> et marque le thème : « quant à A ». です rend polie une phrase dont le prédicat est un nom ou un adjectif en な. Le thème n’est pas toujours le sujet grammatical.</p><ul><li>私は留学生です。 — Je suis étudiant étranger.</li><li>あの方は先生です。 — Cette personne est professeur.</li></ul><p><strong>Négation :</strong> A は B ではありません ; à l’oral, on emploie aussi B じゃありません.</p><ul><li>私は先生ではありません。 — Je ne suis pas professeur.</li></ul><p><strong>Question :</strong> Ajoutez か à la fin d’une phrase polie. À l’écrit, le point d’interrogation est facultatif.</p><ul><li>あの方は先生ですか。 — Cette personne est-elle professeur ?</li></ul><p><strong>Lien entre prédicats :</strong> B で relie un prédicat nominal ou un adjectif en な au prédicat suivant. Ce で est une forme de liaison de la copule, et non la particule indiquant le lieu d’une action.</p><ul><li>田中さんは先生で、作家です。 — Tanaka est professeur et écrivain.</li></ul><h2 id="demonstratifs" tabindex="-1">Démonstratifs <a class="header-anchor" href="#demonstratifs" aria-label="Permalink to &quot;Démonstratifs&quot;">​</a></h2><p><strong>Règle :</strong> La première syllabe indique la position du référent : <strong>こ</strong> près du locuteur, <strong>そ</strong> près de l’interlocuteur ou pour quelque chose déjà mentionné, <strong>あ</strong> loin des deux, et <strong>ど</strong> pour une question. Dans une conversation, そ et あ peuvent aussi renvoyer à un élément connu ou à un souvenir commun ; la distance physique n’est qu’un point de départ.</p><table tabindex="0"><thead><tr><th>Position</th><th>Objet</th><th>Lieu</th><th>Direction / personne (poli)</th></tr></thead><tbody><tr><td>Près du locuteur</td><td>これ</td><td>ここ</td><td>こちら</td></tr><tr><td>Près de l’interlocuteur</td><td>それ</td><td>そこ</td><td>そちら</td></tr><tr><td>Loin des deux</td><td>あれ</td><td>あそこ</td><td>あちら</td></tr><tr><td>Question</td><td>どれ</td><td>どこ</td><td>どちら</td></tr></tbody></table><ul><li>これは私の本です。 — C’est mon livre.</li><li>駅はどちらですか。 — Dans quelle direction se trouve la gare ? (poli)</li></ul><p>Selon le contexte, こちら／そちら／あちら／どちら peuvent aussi désigner poliment une personne ou un choix.</p><h2 id="n1-に-n2-が-あります-います" tabindex="-1">N1 に N2 が あります／います <a class="header-anchor" href="#n1-に-n2-が-あります-います" aria-label="Permalink to &quot;N1 に N2 が あります／います&quot;">​</a></h2><p><strong>Règle :</strong> Cette construction introduit N2 comme se trouvant à l’endroit N1. に indique le lieu ; が indique ce qui s’y trouve. Employez <strong>あります</strong> pour les objets et les plantes, <strong>います</strong> pour les personnes et les animaux.</p><ul><li>机の上に本があります。 — Il y a un livre sur le bureau.</li><li>教室に学生がいます。 — Il y a des étudiants dans la salle de classe.</li></ul><p>Pour exprimer la possession, une personne peut servir de point de référence : 私には兄がいます。 — J’ai un frère aîné (littéralement : « quant à moi, il existe un frère aîné »).</p><h2 id="n1-には-n2-が-あります-います" tabindex="-1">N1 には N2 が あります／います <a class="header-anchor" href="#n1-には-n2-が-あります-います" aria-label="Permalink to &quot;N1 には N2 が あります／います&quot;">​</a></h2><p><strong>Règle :</strong> には réunit に, qui indique le lieu, et は, qui marque le thème ou le contraste. N1 devient le cadre de l’énoncé, avec parfois un contraste implicite avec d’autres lieux ou personnes. Choisissez あります／います selon N2.</p><ul><li>この町には大きな公園があります。 — Cette ville possède un grand parc.</li><li>私のクラスには留学生がいます。 — Il y a des étudiants étrangers dans ma classe.</li></ul><p>Comparez <strong>教室に学生がいます</strong> (« Il y a des étudiants dans la salle de classe ») et <strong>教室には学生がいます</strong> (« Dans la salle de classe, il y a des étudiants ») : la seconde phrase met davantage l’accent sur le lieu.</p><h2 id="n1-は-n2-に-あります-います" tabindex="-1">N1 は N2 に あります／います <a class="header-anchor" href="#n1-は-n2-に-あります-います" aria-label="Permalink to &quot;N1 は N2 に あります／います&quot;">​</a></h2><p><strong>Règle :</strong> Utilisez cet ordre quand N1 est déjà connu et que vous voulez dire <strong>où</strong> il se trouve. は marque le thème connu ; に marque son emplacement. Choisissez あります／います selon N1.</p><ul><li>本は机の上にあります。 — Le livre est sur le bureau.</li><li>先生は職員室にいます。 — Le professeur est dans la salle des professeurs.</li></ul><p><strong>机の上に本があります</strong> introduit l’existence d’un livre ; <strong>本は机の上にあります</strong> donne l’emplacement d’un livre déjà connu.</p><h2 id="passe-predicat-nominal" tabindex="-1">Passé : prédicat nominal <a class="header-anchor" href="#passe-predicat-nominal" aria-label="Permalink to &quot;Passé : prédicat nominal&quot;">​</a></h2><p><strong>Règle :</strong> Dans une phrase nominale polie, です devient <strong>でした</strong>. Le passé négatif poli est <strong>ではありませんでした</strong> (ou, dans la conversation, <strong>じゃありませんでした</strong>). Ces formes s’emploient aussi avec les adjectifs en な.</p><table tabindex="0"><thead><tr><th>Sens</th><th>Modèle</th><th>Exemple</th></tr></thead><tbody><tr><td>Passé affirmatif</td><td>A は B でした</td><td>昨日は休みでした。 — Hier était un jour de repos.</td></tr><tr><td>Passé négatif</td><td>A は B ではありませんでした</td><td>昨日は休みではありませんでした。 — Hier n’était pas un jour de repos.</td></tr></tbody></table><p>Au style neutre, on emploie <strong>だった</strong> et <strong>ではなかった</strong> (ou <strong>じゃなかった</strong>) : 昨日は休みだった。 — Hier était un jour de repos.</p><h2 id="passe-predicat-verbal" tabindex="-1">Passé : prédicat verbal <a class="header-anchor" href="#passe-predicat-verbal" aria-label="Permalink to &quot;Passé : prédicat verbal&quot;">​</a></h2><p><strong>Règle :</strong> Au style poli, <strong>～ます</strong> devient <strong>～ました</strong> au passé affirmatif et <strong>～ません</strong> devient <strong>～ませんでした</strong> au passé négatif. La forme passée au style neutre dépend du groupe verbal : on ne peut pas simplement remplacer ます par た.</p><table tabindex="0"><thead><tr><th>Sens</th><th>Style poli</th><th>Style neutre</th></tr></thead><tbody><tr><td>Passé affirmatif</td><td>昨日、映画を見ました。 — J’ai regardé un film hier.</td><td>昨日、映画を見た。</td></tr><tr><td>Passé négatif</td><td>昨日、映画を見ませんでした。 — Je n’ai pas regardé de film hier.</td><td>昨日、映画を見なかった。</td></tr></tbody></table><p>Par exemple : 行きます → 行きました → 行った, tandis que 食べます → 食べました → 食べた.</p><h2 id="mots-interrogatifs-avec-が" tabindex="-1">Mots interrogatifs avec が <a class="header-anchor" href="#mots-interrogatifs-avec-が" aria-label="Permalink to &quot;Mots interrogatifs avec が&quot;">​</a></h2><p><strong>Règle :</strong> Quand on demande <strong>qui ou quoi est le sujet</strong>, le mot interrogatif prend が : 誰が／何が. La réponse emploie souvent が pour identifier ce sujet. On peut toutefois employer は si l’on présente la personne ou la chose comme un thème déjà connu, ou si l’on établit un contraste ; la règle « une question avec が exige une réponse avec が » est trop absolue.</p><ul><li>誰が来ましたか。 — Qui est venu ?</li><li>田中さんが来ました。 — Tanaka est venu.</li><li>何がありますか。 — Qu’y a-t-il ?</li><li>机の上に本があります。 — Il y a un livre sur le bureau.</li></ul><h2 id="この-その-あの-どの" tabindex="-1">この／その／あの／どの <a class="header-anchor" href="#この-その-あの-どの" aria-label="Permalink to &quot;この／その／あの／どの&quot;">​</a></h2><p><strong>Règle :</strong> Ce sont des <strong>連体詞</strong> (mots qui modifient directement un nom). Ils doivent être suivis d’un nom : この本 (« ce livre-ci »), その本 (« ce livre près de vous / déjà mentionné »), あの本 (« ce livre là-bas »), どの本 (« quel livre »). Pour désigner un objet sans répéter le nom, utilisez plutôt これ／それ／あれ／どれ.</p><ul><li>この本は面白いです。 — Ce livre est intéressant.</li><li>これは面白いです。 — Ceci est intéressant.</li><li>どの本があなたのですか。 — Quel livre est le vôtre ?</li><li>どれがあなたのですか。 — Lequel est le vôtre ?</li></ul>',42)])])}const c=t(r,[["render",o]]);export{m as __pageData,c as default};
